/*
 * A266300  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 15" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A266300
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   not stated
 * Range:     u8 n <= 9999, u16 n <= 9999, u32 n <= 9999, u64 n <= 9999,
 *            u128 n <= 9999, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * This function computes OEIS A266300: the values read row‑by‑row from the
 * triangular states of cellular automaton Rule 15 starting with a single ON
 * cell.  The entry can be described as follows:
 *
 * Let r = ⌊√n⌋ and k = n – r²  (0 ≤ k ≤ 2r).  Then
 *   • if r is odd   →  a(n) = 1  for all k < 2r,  a(n) = 0  for k = 2r;
 *   • if r is even →  a(n) = 0  for all k < 2r,  a(n) = 1  for k = 2r.
 *
 * Equivalently:
 *   a(n) = ( (r & 1) && (k < 2*r) ) || ( (!(r & 1)) && (k == 2*r) ).
 *
 * This formula reproduces the given terms:
 * a(0..2)=1, a(3..7)=0, a(8..14)=1, a(15..23)=0, a(24)=1, ….
 */

static idx_t isqrt_uint64(idx_t n)
{
    idx_t lo = 0, hi = n;
    while (lo < hi) {
        idx_t mid = lo + ((hi - lo + 1) >> 1);
        if (mid > 0 && mid > n / mid) {  // mid*mid > n, but avoid overflow
            hi = mid - 1;
        } else {
            lo = mid;
        }
    }
    return lo;
}

seq_t a(idx_t n)
{
    idx_t r = isqrt_uint64(n);
    idx_t k = n - r * r;   /* r*r never overflows for 64‑bit n */

    if ((r & 1) == 0) { /* r even */
        return (k == 2 * r) ? (seq_t)1 : (seq_t)0;
    } else {            /* r odd */
        return (k == 2 * r) ? (seq_t)0 : (seq_t)1;
    }
}
